const data = $json;

let result = data.output;

if (typeof result !== "string") {
  result = JSON.stringify(result);
}

result = result
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(result);
} catch (error) {
  throw new Error("Invalid JSON returned by AI");
}

return {
  json: {
    ...data,
    ...parsed
  }
};

const items = $input.all();

const requiredFields = [
  "Issue_ID",
  "Customer_ID",
  "Customer_Name",
  "Customer_Email",
  "Issue_Subject",
  "Issue_Description",
  "Channel",
  "Product",
  "Issue_Date",
  "Previous_Issues"
];

const validItems = [];
const invalidItems = [];

for (const item of items) {

  const data = item.json;

  const missingFields = requiredFields.filter(
    field =>
      data[field] === undefined ||
      data[field] === null ||
      String(data[field]).trim() === ""
  );

  const previousIssues =
    Number(data.Previous_Issues);

  const issueDate =
    new Date(data.Issue_Date);

  const dateValid =
    !isNaN(issueDate.getTime());

  if (
    missingFields.length === 0 &&
    !isNaN(previousIssues) &&
    previousIssues >= 0 &&
    dateValid
  ) {

    validItems.push({
      ...data,
      Previous_Issues:
        previousIssues
    });

  } else {

    invalidItems.push({
      issue_id:
        data.Issue_ID || "Unknown",

      missing_fields:
        missingFields
    });
  }
}

return [
  {
    json: {

      data_valid:
        invalidItems.length === 0,

      total_issues:
        items.length,

      valid_issues:
        validItems.length,

      invalid_issues:
        invalidItems.length,

      invalid_details:
        invalidItems,

      issue_data:
        validItems
    }
  }
];

const issues = $json.issue_data;

const results = [];

const concernKeywords = [
  "crash",
  "error",
  "failed",
  "failure",
  "broken",
  "charged twice",
  "not received",
  "not delivered",
  "refund",
  "cannot access",
  "unable",
  "problem",
  "issue",
  "urgent"
];

for (const issue of issues) {

  const description =
    String(issue.Issue_Description);

  const text =
    description.toLowerCase();

  const previousIssues =
    Number(issue.Previous_Issues);

  let concernScore = 0;

  for (const keyword of concernKeywords) {

    if (text.includes(keyword)) {
      concernScore += 1;
    }
  }

  if (previousIssues >= 3) {
    concernScore += 2;
  } else if (previousIssues >= 1) {
    concernScore += 1;
  }

  if (description.length > 500) {
    concernScore += 1;
  }

  let initialSeverity;

  if (concernScore >= 5) {
    initialSeverity = "HIGH";
  } else if (concernScore >= 3) {
    initialSeverity = "MEDIUM";
  } else {
    initialSeverity = "LOW";
  }

  results.push({

    ...issue,

    Concern_Score:
      concernScore,

    Initial_Severity:
      initialSeverity
  });
}

return [
  {
    json: {
      prepared_issues:
        results
    }
  }
];

